use std::io::{Read,Write};use spore_core::{cell_fresh_sweep_registration_v1::{Endpoint,Slot},cell_sweep_sorted_crossing_v1::{reorder,Side,Direction}};
fn main()->Result<(),Box<dyn std::error::Error>>{let mut input=Vec::new();std::io::stdin().read_to_end(&mut input)?;if input.len()!=176{return Err("expected four 44-byte cases".into())}let mut out=Vec::new();for (case,row) in input.chunks_exact(44).enumerate(){let u16at=|p:usize|u16::from_le_bytes(row[p..p+2].try_into().unwrap());let u32at=|p:usize|u32::from_le_bytes(row[p..p+4].try_into().unwrap());let axis=u32at(0) as usize;let mut slots=vec![Slot{actor:0x10001,tag:0,endpoint_links:[0x41,0x42,0x43,0x44]},Slot{actor:0x20002,tag:0,endpoint_links:[0x51,0x52,0x53,0x54]}];for j in 0..2{for side in 0..2{slots[j].endpoint_links[axis+2*side]=u16at(4+2*(j*2+side))}}let endpoints:Vec<_>=(0..4).map(|i|{let p=12+i*8;Endpoint{opening:u16at(p),slot:u16at(p+2),value_bits:u32at(p+4)}}).collect();let (side,direction)=match case{0=>(Side::Minimum,Direction::Left),1=>(Side::Maximum,Direction::Right),2=>(Side::Minimum,Direction::Right),_=>(Side::Maximum,Direction::Left)};let result=reorder(&slots,axis,&endpoints,0,side,direction).map_err(|e|format!("{e:?}"))?;for s in result.slots{out.extend(s.actor.to_le_bytes());out.extend(s.tag.to_le_bytes());for x in s.endpoint_links{out.extend(x.to_le_bytes())}}for e in result.endpoints{out.extend(e.opening.to_le_bytes());out.extend(e.slot.to_le_bytes());out.extend(e.value_bits.to_le_bytes())}out.extend([0xcc;16]);out.extend(2u32.to_le_bytes());}std::io::stdout().write_all(&out)?;Ok(())}
